def grid_to_regions(grid, H, W, out_h=3, out_w=6):
    """Map input grid to output regions"""
    h_splits = [i * H // out_h for i in range(out_h + 1)]
    v_splits = [i * W // out_w for i in range(out_w + 1)]

    regions = [[0]*out_w for _ in range(out_h)]

    for r in range(H):
        for c in range(W):
            if grid[r][c] == 2:
                reg_r = min(next(i for i, s in enumerate(h_splits) if s > r), out_h-1)
                reg_c = min(next(i for i, s in enumerate(v_splits) if s > c), out_w-1)
                regions[reg_r][reg_c] += 1

    return regions

